const tabId = 1962625065;

const shadowCheck = await browserjs(tabId, () => {
  function getAllElements(root = document) {
    let elements = [];
    const children = root.querySelectorAll('*');
    for (const child of children) {
      elements.push(child);
      if (child.shadowRoot) {
        elements.push(...getAllElements(child.shadowRoot));
      }
    }
    return elements;
  }
  const all = getAllElements();
  const matched = [];
  for (const el of all) {
    const text = el.innerText || el.textContent || '';
    if (/overview|submission|guideline|contribut/i.test(text) && text.length < 100) {
      matched.push({
        tag: el.tagName,
        text: text.trim(),
        href: el.href || el.getAttribute('href') || null
      });
    }
  }
  return {
    totalElements: all.length,
    matched: matched.slice(0, 30)
  };
});

