const tabId = 1962625065;

const linkHierarchy = await browserjs(tabId, () => {
  function findHost(el) {
    let curr = el;
    const path = [];
    while (curr) {
      path.push(curr.tagName + (curr.id ? '#' + curr.id : '') + (curr.className ? '.' + curr.className : ''));
      if (curr.parentNode) {
        curr = curr.parentNode;
      } else if (curr.host) {
        path.push('[ShadowRoot of ' + curr.host.tagName + ']');
        curr = curr.host;
      } else {
        break;
      }
    }
    return path;
  }

  function getAllElements(root = document) {
    let elements = [];
    const children = root.querySelectorAll('*');
    for (const child of children) {
      elements.push(child);
      if (child.shadowRoot) {
        elements.push(...getAllElements(child.shadowRoot));
      }
    }
    return elements;
  }

  const all = getAllElements();
  const target = all.find(el => el.tagName === 'A' && el.href && el.href.includes('360004016474'));
  return target ? findHost(target) : null;
});

console.log(linkHierarchy);

